1	// The executor (tasks-dispatch DESIGN §6) — a pull worker over the queue. Each
2	// iteration: pick the next ready item, claim it by a verified lease, re-evaluate
3	// the precondition (the scheduler run asked once at the anchor; a chained stage
4	// re-derives world state rather than trusting a verdict passed forward), then on
5	// a go run code-work and either converge (agentless) or hand off to an agent
6	// session; on a no-go close the item with the reason on record — the next
7	// occurrence is the scheduler run's ask at the task's next anchor (#1115).
8	//
9	// An executor's whole interface is issue read/write plus the repo at HEAD, which
10	// is what makes it platform-agnostic: the reference deployment is a job in the
11	// vendored workflows (the scheduler run's post-scheduler run drain, and a `labeled`-event run for
12	// latency), but a runner anywhere with an issues-scope token qualifies. Nothing
13	// enumerates executors; identity is self-declared in the claim comment.
14	//
15	// The pure decisions live at the top and test with fixtures; the shell below is
16	// the GitHub/code-work/invocation I/O around them.
17	
18	import { pathToFileURL } from 'node:url';
19	import { isSuspended, readSuspendedNow, suspendedNotice, SUSPEND_ALL_VAR } from './suspend.mjs';
20	import { readyDependents } from './readiness.mjs';
21	import { HEARTBEAT_MS, heartbeatComment, withHeartbeat } from './heartbeat.mjs';
22	import { renderTaskExec } from '../run-record.mjs';
23	import { swapStatus, clearStatus } from './apply-status.mjs';
24	import {
25	  READY, URGENT, EXECUTING, AGENT, NEEDS_HUMAN,
26	  STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT, isStatus,
27	  TASK_DONE, TASK_OBSOLETE, QUEUE_LABELS, QUEUED_LABEL, isStandingItem,
28	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_FAILURE, triageLabelFor,
29	  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
30	  parseWorkItemTitle, isWorkItemTitle, parseWorkItemBody, parseContextLines, mergeContext, withNotBefore, withSection, editItemBody, hasLabel, DELIVERED_HEADING, LEGACY_DELIVERED_HEADINGS,
31	  LAST_VERDICT_HEADING, lastVerdictLines } from './work-item.mjs';
32	
33	const titleOf = (item) => (item.title ?? '').trim();
34	// An item somebody is executing — the executor holds it, or the agent it handed to
35	// does. Decoded, never a literal label test: the item may wear any engine's spelling.
36	const running = (item) => isStatus(item, STATUS_RUNNING_EXECUTOR) || isStatus(item, STATUS_RUNNING_AGENT);
37	// WHICH TASK AN ITEM NAMES. A filed `[claudinite-work]` item says so in its title;
38	// a marked issue (DESIGN §16.1) keeps its own human title and names its task in the
39	// machine block's first line, so the id comes from the task whose worker path that
40	// is. `pathTo` is that lookup, injected because only the run holds the task set.
41	const taskIdOf = (item, pathTo = () => null) => {
42	  const p = parseWorkItemTitle(item.title);
43	  if (p) return `${p.pack}/${p.task}`;
44	  return pathTo(parseWorkItemBody(item.body).taskPath) ?? null;
45	};
46	
47	// The pick order (DESIGN §6.1): urgent first, then RANDOM among the ready, with
48	// two skip rules read live at pick time. Random rather than oldest-first because
49	// nothing leans on FIFO aging — the stale-ready escalation is period-scale — while
50	// a deterministic order lets one unlucky head dominate every run of a chain
51	// (DESIGN §15.20).
52	//
53	//  - SAME-TITLE MUTEX (S15/F6): skip an item whose exact title has another open
54	//    item executing or handed to an agent — one task, one execution at a time,
55	//    while a fan-out's distinct qualifiers still parallelize.
56	//  - THE `after` YIELD (S23): skip a scheduled item whose task declares `after:
57	//    [T]` while T's standing item is live THIS CYCLE (ready / executing / agent).
58	//    A declined upstream holds nothing back — it has no item at all (a no files
59	//    only a board row, #1115) — and neither does one sitting `needs-human`: a
60	//    broken upstream must not halt its dependents indefinitely.
61	//
62	// `open` is every open work item; `taskAfter(id)` gives a task's declared
63	// upstreams as `<pack>/<task>` ids, and `frequencyOf(id)` that task's declared
64	// frequency at HEAD — which is half of what says whether an item is a standing
65	// occurrence or an ad-hoc run (§15.26). `random` is the tie-break draw, injected
66	// so a test can pin an order the production call deliberately does not have.
67	export function pickOrder(open = [], { taskAfter = () => [], frequencyOf = () => null, random = Math.random, pathTo = () => null } = {}) {
68	  const idOf = (item) => taskIdOf(item, pathTo);
69	  const live = (item) => [STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT].some((s) => isStatus(item, s));
70	  const standing = (item) => isStandingItem(item, frequencyOf(idOf(item)));
71	  const liveUpstream = (upstreamId) => open.some((o) =>
72	    idOf(o) === upstreamId && standing(o) && live(o));
73	  // One draw per item, taken once: a comparator that called `random()` per
74	  // comparison would not be a consistent ordering, and `Array.sort` on one is
75	  // free to produce anything at all.
76	  const draw = new Map(open.map((i) => [i.number, random()]));
77	
78	  return open
79	    .filter((i) => isStatus(i, STATUS_READY))
80	    .filter((i) => !open.some((o) => o.number !== i.number && titleOf(o) === titleOf(i)
81	      && running(o)))
82	    .filter((i) => {
83	      if (!standing(i)) return true;
84	      return !taskAfter(idOf(i)).some(liveUpstream);
85	    })
86	    .sort((a, b) =>
87	      (hasLabel(b, URGENT) ? 1 : 0) - (hasLabel(a, URGENT) ? 1 : 0)
88	      || draw.get(a.number) - draw.get(b.number));
89	}
90	
91	// The claim comment carries WHO and WHEN — the executor id and its run URL —
92	// because executor identity is an unbounded set and must never become a label
93	// (DESIGN §4).
94	export const claimComment = ({ executor, runUrl, at }) =>
95	  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;
96	
97	// Who won the claim, out of an item's comments (DESIGN §6.2). Three precisions,
98	// each an implicit assumption made explicit:
99	//
100	//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment
101	//    `created_at` has one-second granularity, so simultaneous claims tie on time;
102	//    comment ids are server-assigned and strictly increasing — a total order the
103	//    protocol gets for free. Nothing here compares runner clocks.
104	//  - THE ARBITER IS EPISODE-SCOPED (F18): the earliest claim SINCE the item last
105	//    became ready. Over an item's lifetime dead claims accumulate (every reclaim
106	//    and revert leaves one), and arbitrating over all of them makes a dead claim
107	//    outrank every future live claimant — the item then livelocks through reclaim
108	//    cycles forever. The reclaim / revert / re-queue comment is the boundary.
109	//  - THE LABEL SWAP IS NOT THE ARBITER, so a torn swap can never mint a second
110	//    owner; it can only leave an item with no state label, which the janitor
111	//    repairs.
112	export function claimWinner(comments = []) {
113	  const sorted = [...comments].sort((a, b) => a.id - b.id);
114	  const boundary = sorted.filter((c) => (c.body ?? '').includes(EPISODE_MARKER)).at(-1);
115	  const claims = sorted
116	    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER))
117	    .filter((c) => !boundary || c.id > boundary.id);
118	  return claims[0] ?? null;
119	}
120	
121	// After WINNING a claim, re-verify the pick filters against live state (F15). The
122	// filters read possibly-stale state, so two executors can pass them simultaneously
123	// and claim DIFFERENT items the filters should have serialized — a twin pair, or
124	// an upstream and its dependent. The per-item lease cannot see that: it protects
125	// one item, not one title. If a conflicting item now holds an EARLIER claim
126	// (comment id — the same arbiter the lease trusts), this executor reverts its own
127	// claim and moves on. Bounded, deterministic, and the earlier claim never notices.
128	export function conflictsWithEarlierClaim(item, myClaimId, others, { taskAfter = () => [], frequencyOf = () => null, pathTo = () => null } = {}) {
129	  const idOf = (i) => taskIdOf(i, pathTo);
130	  const standing = (i) => isStandingItem(i, frequencyOf(idOf(i)));
131	  const upstreams = standing(item) ? taskAfter(idOf(item)) : [];
132	  return others.some((o) => {
133	    if (o.number === item.number) return false;
134	    if (!running(o)) return false;
135	    const conflicting = titleOf(o) === titleOf(item)
136	      || (upstreams.includes(idOf(o)) && standing(o));
137	    return conflicting && o.claimId != null && o.claimId < myClaimId;
138	  });
139	}
140	
141	// The no-go outcome (DESIGN §6.4, as amended by #1115): every decline CLOSES
142	// the item with the reason. The roll — `Not-before` stamped, open-blocked,
143	// waiting out the period — is gone: "asked and declined" lives on the schedule
144	// board, and a scheduled item's next occurrence is the scheduler run's ask at
145	// its next anchor (the closed-at half of the occurrence guard keeps this
146	// period consumed). `standing` marks whether the close should say so.
147	// The `(item, task, schedule, now, reason)` signature is kept — callers and
148	// fielded tests pass all five, and the standing/ad-hoc distinction still
149	// shapes the close's wording.
150	export function noGoPlan(item, task, schedule, now, reason) {
151	  return {
152	    kind: 'close',
153	    outcome: TASK_OBSOLETE,
154	    stateReason: 'not_planned',
155	    reason,
156	    standing: isStandingItem(item, task?.decl?.frequency),
157	  };
158	}
159	
160	// --- the shell ----------------------------------------------------------------
161	
162	const nowIso = () => new Date().toISOString();
163	
164	// ONE EXECUTOR RUN DRAINS THE QUEUE (DESIGN §6, §10, decision §15.30, reversing
165	// §15.22's one-item run). Actions bills each job's runtime rounded UP to the next
166	// minute, so a day's cost is the RUN count: a run that performed one item paid a
167	// whole invocation — checkout, setup, rounding — per item. So a run claims an
168	// item, sees it to its settle, then picks the next, and ends when nothing is
169	// pickable. Items still settle ONE AT A TIME: this moved the run boundary, not
170	// the occupancy model, and capacity is still executor width.
171	//
172	// What still starts a run is the enumerable list of §10, each cause on the
173	// record: the scheduler run's drain job (dispatched only when that run leaves
174	// something pickable), a label event, an agent session's close-time drain, and
175	// the workflow's failure-continuation job when a run dies mid-drain. Self-
176	// re-dispatch retired with the one-item run — the remainder is this run's own.
177	//
178	// AN ITEM THIS RUN LET GO OF IS NEVER RE-ATTEMPTED BY IT. Losing a claim race
179	// leaves the item running under its winner, so the next pick simply does not see
180	// it — but a post-claim REVERT puts the item back to ready, and re-picking what
181	// this run just returned to the queue is an unbounded loop, not a retry. Both
182	// exits are therefore recorded in `standDown` and skipped for the rest of the
183	// run; the executor that won, and the scheduler run behind it, carry those.
184	//
185	// The loop terminates because every iteration either settles an item (which
186	// leaves the ready state) or stands down from one — and the only items that
187	// newly become pickable are the dependents a close releases, which is the
188	// chaining this exists to do. Its outer bound is the workflow's own timeout.
189	//
190	// Injected seams keep the run testable end to end without GitHub, code-work
191	// subprocesses or an invocation endpoint. `heldNow` is the operator hold, asked
192	// between items (§15.30): `vars.*` reaches the env at start only, so a drain that
193	// outlives the hold's arrival can only see it by asking.
194	export async function runExecutor({
195	  gh, repo, root, config, tasks, executorId, runUrl = null,
196	  now = () => new Date(), random = Math.random, heartbeatMs = HEARTBEAT_MS,
197	  collectSignalsFor, runTaskCodeWork, invokeAgent, heldNow = null, log = console.log,
198	}) {
199	  const api = await import('../github.mjs');
200	  const { listOpenWorkItems } = await import('./read.mjs');
201	  const schedule = config.taskScheduler;
202	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
203	  const taskAfter = (id) => byId.get(id)?.decl?.schedule_after ?? [];
204	  const frequencyOf = (id) => byId.get(id)?.decl?.frequency ?? null;
205	  // A marked issue names its task by worker path, so the run needs the inverse of
206	  // the id map — built from the same task set, so a path this repo does not carry
207	  // resolves to nothing and the item is malformed rather than guessed at.
208	  const byPath = new Map(tasks.map((t) => [t.taskPath, `${t.pack}/${t.id}`]));
209	  const pathTo = (p) => byPath.get(p) ?? null;
210	  const done = [];
211	  // Items this run has let go of — a lost race, a reverted claim — and must not
212	  // pick again. Without it a revert re-picks what it just returned to the queue.
213	  const standDown = new Set();
214	
215	  for (;;) {
216	    // Read live every time: the settle just made may have readied a dependent,
217	    // and another executor may have taken what was pickable a moment ago.
218	    const open = await listOpenWorkItems(gh, repo);
219	    const candidate = pickOrder(open, { taskAfter, frequencyOf, random, pathTo })
220	      .find((i) => !standDown.has(i.number));
221	    if (!candidate) break;
222	
223	    // --- claim: the verified lease ------------------------------------------
224	    await swapStatus(api, gh, repo, candidate, STATUS_READY, EXECUTING);
225	    await api.comment(gh, repo, candidate.number, claimComment({
226	      executor: executorId, runUrl, at: nowIso(),
227	    }));
228	    const comments = await api.listComments(gh, repo, candidate.number);
229	    const winner = claimWinner(comments);
230	    const mine = [...comments]
231	      .sort((a, b) => a.id - b.id)
232	      .filter((c) => (c.body ?? '').includes(CLAIM_MARKER) && (c.body ?? '').includes(`executor \`${executorId}\``))
233	      .at(-1);
234	    if (!winner || winner.id !== mine?.id) {
235	      // The loser reverts nothing — the winner's labels already stand. It does
236	      // strike its own claim (F24): letting go covers losing too, and a claim left
237	      // behind here outlives the winner's episode and becomes the earliest of the
238	      // NEXT one, moving the livelock one episode along.
239	      await strikeClaim(api, gh, repo, mine);
240	      standDown.add(candidate.number);
241	      log(`- #${candidate.number}: another executor holds this episode's earliest claim — leaving it to them`);
242	      continue;
243	    }
244	
245	    // --- post-claim re-verify (F15) -----------------------------------------
246	    const others = await withClaimIds(api, gh, repo, await listOpenWorkItems(gh, repo), candidate.number);
247	    if (conflictsWithEarlierClaim(candidate, winner.id, others, { taskAfter, frequencyOf, pathTo })) {
248	      await api.comment(gh, repo, candidate.number,
249	        `${EPISODE_MARKER}\nReverting this claim: a conflicting item holds an earlier claim this cycle. Returning the item to the queue.`);
250	      await swapStatus(api, gh, repo, candidate, STATUS_RUNNING_EXECUTOR, READY);
251	      standDown.add(candidate.number);
252	      log(`- #${candidate.number}: reverted — a conflicting item claimed earlier`);
253	      continue;
254	    }
255	
256	    const outcome = await executeItem({
257	      api, gh, repo, root, config, schedule, byId, pathTo, item: candidate, executorId,
258	      claim: winner, now, heartbeatMs, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
259	    });
260	    done.push({ issue: candidate.number, outcome });
261	
262	    // --- the hold, between items (§15.30) -----------------------------------
263	    // Asked after the settle rather than before the pick that follows it, so a
264	    // run that had nothing more to do never spends the read. The item just
265	    // finished is untouched: suspension stops picking, never running work.
266	    if (heldNow && await heldNow()) {
267	      log(`- ${SUSPEND_ALL_VAR} is set: this drain stops here, holding nothing. Items stay exactly as they are.`);
268	      break;
269	    }
270	  }
271	  return done;
272	}
273	
274	// The claim id of each live item, so the post-claim verify can compare episodes.
275	// One comment read per conflicting-looking item, not per item in the repo.
276	async function withClaimIds(api, gh, repo, items, selfNumber) {
277	  const out = [];
278	  for (const i of items) {
279	    if (i.number === selfNumber || !running(i)) { out.push(i); continue; }
280	    const winner = claimWinner(await api.listComments(gh, repo, i.number));
281	    out.push({ ...i, claimId: winner?.id ?? null });
282	  }
283	  return out;
284	}
285	
286	// One claimed item, from validation through to a terminal state (or a hand-off).
287	async function executeItem({
288	  api, gh, repo, root, config, schedule, byId, pathTo = () => null, item, executorId, claim,
289	  now, heartbeatMs, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
290	}) {
291	  // What a close needs beyond the item itself: the clock for a dependent's
292	  // `Not-before`, and somewhere to say what it released.
293	  const ctx = { now, log };
294	  const parsed = parseWorkItemTitle(item.title);
295	  const { taskPath } = parseWorkItemBody(item.body);
296	  // A marked issue's identity is its machine block, not its title (§16.1): the id
297	  // is whichever task owns the worker path the block names.
298	  const id = parsed ? `${parsed.pack}/${parsed.task}` : pathTo(taskPath);
299	  const task = id ? byId.get(id) : null;
300	  // The exec record joins back to the work by pack and task, which a marked issue's
301	  // human title cannot supply — so the resolved id travels with the item.
302	  item.taskId = id;
303	
304	  // --- validate in code, before anything trusts the issue ------------------
305	  if (!taskPath || (!parsed && !id)) {
306	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
307	      'This work item is malformed — its title or first body line does not name a task. Possible forgery; a human should look at it.', 'invalid');
308	    return 'needs-human';
309	  }
310	  if (!task) {
311	    await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_OBSOLETE, 'not_planned',
312	      `\`${id}\` is not a task this repo carries at HEAD (the pack may be undeclared, or the task removed). Closing obsolete.`, 'task-gone', ctx);
313	    return 'obsolete';
314	  }
315	  if (task.taskPath !== taskPath) {
316	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
317	      `This item's task path (\`${taskPath}\`) is not where \`${id}\` lives at HEAD (\`${task.taskPath}\`). Not running it.`, 'invalid');
318	    return 'needs-human';
319	  }
320	
321	  // --- the single precondition evaluation (DESIGN §6.4) --------------------
322	  const at = now();
323	  const fields = parseWorkItemBody(item.body);
324	  // The signals are collected FOR THIS OCCURRENCE, and the precondition judges over
325	  // it: a request item's verdict is about the issue it names, which no signal bundle
326	  // can single out on its own (DESIGN §16.4).
327	  const signals = await collectSignalsFor(task, at, item);
328	  const verdict = evaluatePrecondition(task, signals, config.packConfig?.[task.pack] ?? {}, fields);
329	
330	  // A PRECONDITION THAT COULD NOT ANSWER IS A RUN FAILURE, NOT A VERDICT (F27). A
331	  // decline is a decision about the world; one taken on an API that would not answer
332	  // is a guess, and its write-backs cannot land — for a request that would strand
333	  // the issue armed-but-queued forever, the request silently eaten. So the item
334	  // parks open in the failure lane, where the ordinary re-queue lever retries it
335	  // once the API recovers, and nothing is written to whatever it could not read.
336	  if (verdict.error) {
337	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
338	      `This run could not be decided: ${verdict.error}\n\nNothing ran and nothing was written. Re-queue this item (remove the \`${NEEDS_HUMAN}\` labels, add \`${READY}\`) once the cause has cleared.`);
339	    log(`! #${item.number} ${id}: the precondition could not answer — ${verdict.error}`);
340	    return 'needs-human';
341	  }
342	
343	  if (verdict.run !== true) {
344	    const plan = noGoPlan(item, task, schedule, at, verdict.reason || 'no work');
345	    // A DECLINED REQUEST IS DISARMED IN THE SAME CONVERGENCE (DESIGN §16.5).
346	    // Nothing else would: an issue left carrying `claude-queued` after its run was
347	    // refused is one no later scheduler run adopts and no person is told about, and one
348	    // whose mark — if re-applied — walks into the same refusal forever.
349	    // A LEGACY shadow item wrote its decline back to the issue it named. A marked
350	    // issue IS the item, so the decline's comment and its `rejected` status already
351	    // land where the person is looking and there is nothing to mirror (§16.5).
352	    if (fields.request && fields.request !== item.number) {
353	      await declineRequest(api, gh, repo, fields.request, item.number, plan.reason);
354	    }
355	    // A DECLINE IS A COMPLETED RUN, not a failure: the executor asked, got a
356	    // no, and closed the occurrence — so the record says `success` and the
357	    // reason sits beside it in the same comment.
358	    await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_OBSOLETE, 'not_planned',
359	      `The precondition declined: ${plan.reason}`
360	      + (plan.standing
361	        ? '\n\nThis task\'s next occurrence is decided at its next anchor; declined occurrences are recorded on the schedule board.'
362	        : ''), 'success', ctx);
363	    return 'obsolete';
364	  }
365	
366	  // --- code-work (unchanged contract), then converge or hand off -------------
367	  // The item's OWN Context is scope too, not decoration: an operator's parameters
368	  // (`create-work-item --context "REPOS=Alpha Beta"`) live there and nowhere else,
369	  // so code-work sees the union of what the item was created with and what this
370	  // occurrence's precondition added. Passing only the verdict's half is what made
371	  // a hand-created item's parameters unreachable (#974).
372	  const context = mergeContext(parseContextLines(item.body), verdict.context ?? []);
373	  if (task.decl.code_work) {
374	    // The work step may legitimately run for hours (§15.15). While it does, the
375	    // item's only sign of life is this beat — which is also what the scheduler run's leash
376	    // measures, so a long run is legal rather than reclaimed underneath itself.
377	    const result = await withHeartbeat(() => runTaskCodeWork(task, { item, context }), {
378	      intervalMs: heartbeatMs,
379	      log,
380	      beat: (minutes) => api.comment(gh, repo, item.number,
381	        heartbeatComment({ executor: executorId, at: nowIso(), minutes })),
382	    });
383	    if (!result.ok) {
384	      // The worker's own verdict routes the park where it left one; a worker that
385	      // said nothing about why it failed is a `failure` — the lane that means
386	      // "someone reads the trace", which is the only safe default for a run whose
387	      // cause is unknown.
388	      await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, triageLabelFor(result.triage?.kind), claim,
389	        `Code-work failed: ${result.why}${result.triage?.detail ? `\n\nThe worker's own verdict: ${result.triage.detail}` : ''}`
390	        + `${result.detail ? `\n\n\`\`\`\n${result.detail}\n\`\`\`` : ''}`);
391	      return 'needs-human';
392	    }
393	    if (result.missingSecrets?.length) {
394	      await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_ACTION, claim,
395	        `This task declares repo Actions secrets that are not configured: ${result.missingSecrets.join(', ')}. Set them in repo settings and re-queue this item (remove the \`${NEEDS_HUMAN}\` labels, add \`${READY}\`).`);
396	      return 'needs-human';
397	    }
398	    if (!result.agentRequested) {
399	      // A run that deliberately left an UNMERGED PR is not finished, it is waiting
400	      // on a person — so the item stays OPEN at `task:needs-human-approval` rather
401	      // than closing as delivered. It does not hold the task's lane while it waits
402	      // (`isBlockingPark`): the next occurrence is filed on schedule around it, so
403	      // an unreviewed PR delays nobody but its reviewer.
404	      if (result.openPr) {
405	        await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_APPROVAL, claim,
406	          `Code-work did this run's work and opened a PR for you to approve:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
407	          + `\n\nMerge or close #${result.openPr}, then close this item. This task keeps running on schedule meanwhile.`, null);
408	        return 'needs-human';
409	      }
410	      await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_DONE, 'completed',
411	        result.delivered?.length
412	          ? `Code-work did this run's work and left:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
413	          : 'Code-work did this run\'s work; no agent was needed.', 'success', ctx);
414	      return TASK_DONE;
415	    }
416	    return handOff({ api, gh, repo, item, task, id, context, result, executorId, claim, invokeAgent, config, log });
417	  }
418	
419	  // An agentless task with no code-work does nothing (the contract forbids it).
420	  if (task.decl.agent_model === 'none') {
421	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
422	      'This task is agentless but declares no code_work, so there is nothing to run — a contract-forbidden shape that reached the queue.', 'invalid');
423	    return 'needs-human';
424	  }
425	  return handOff({ api, gh, repo, item, task, id, context, result: {}, executorId, claim, invokeAgent, config, log });
426	}
427	
428	// Run one task's precondition. THE only place a precondition is ever called, so a
429	// test that drives this drives what production drives — a precondition first
430	// written to take `{ signals }` passed its own direct-call test and threw on every
431	// real run, which is the failure this seam exists to make impossible.
432	//
433	// A throwing precondition converges to a no-go with the error as its reason: one
434	// task's bad verdict is that item's problem, never the executor's.
435	export function evaluatePrecondition(task, signals, packConfig = {}, item = null) {
436	  try {
437	    return task.decl.precondition(signals, packConfig, item) ?? {};
438	  } catch (e) {
439	    return { run: false, reason: `precondition threw: ${e.message}` };
440	  }
441	}
442	
443	// @deprecated The write-back a refused SHADOW item's issue got — one comment saying
444	// why, and the queued label off, so the request was disarmed rather than left
445	// looking pending. Nothing writes it for an item filed under the one-issue model,
446	// where the item and the issue are the same object; it stays for the shadow items
447	// still draining, whose issue is a different one (DESIGN §16.5).
448	async function declineRequest(api, gh, repo, request, item, reason) {
449	  await api.comment(gh, repo, request,
450	    `Not implementing this: ${reason}\n\nThe queued run (#${item}) is closed and \`${QUEUED_LABEL}\` is removed. `
451	    + 'If this was wrong, mark the issue again — a request is only run when the person who opened it, or somebody who commented `/claude go`, has push access here.');
452	  await api.removeLabel(gh, repo, request, QUEUED_LABEL);
453	}
454	
455	// @deprecated The roll retired with #1115 — nothing writes this any more. Kept
456	// exported because bodies the fielded roll wrote are stored data: the
457	// round-trip test over this writer is what pins `parseLastVerdict`'s decode,
458	// which the migration and the dashboard still read.
459	export function rollBody(body, until, reason, at) {
460	  const stamped = withNotBefore(body, until);
461	  return withSection(stamped, LAST_VERDICT_HEADING, lastVerdictLines({ at, reason, until }));
462	}
463	
464	// Hand off to an agent session (DESIGN §6.6). ONE call per item, ever — which is
465	// what lets this be as short as it is. The nonce goes on the item before the call
466	// and travels in the payload, so the session can prove the fire it arrived on is
467	// the hand-off this item recorded and stop if it is not.
468	async function handOff({ api, gh, repo, item, task, id, context, result, executorId, claim, invokeAgent, config, log }) {
469	  const nonce = `${item.number}-${Math.random().toString(36).slice(2, 10)}`;
470	  // Every section lands in the machine's half of the body — the whole body for a
471	  // filed item, the machine block for a marked issue, whose prose is the person's.
472	  const body = editItemBody(item.body, (machine) => {
473	    let out = machine;
474	    if (context.length) out = withSection(out, 'Context', context);
475	    if (result.delivered?.length) out = withSection(out, DELIVERED_HEADING, result.delivered, LEGACY_DELIVERED_HEADINGS);
476	    if (result.reason) out = withSection(out, 'Why the agent is here', [result.reason]);
477	    return out;
478	  });
479	  await gh(`/repos/${repo}/issues/${item.number}`, { method: 'PATCH', body: { body } });
480	
481	  await swapStatus(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, AGENT);
482	  await api.comment(gh, repo, item.number,
483	    `${HANDOFF_MARKER}\nHanded off by executor \`${executorId}\` — invocation nonce \`${nonce}\`.`);
484	
485	  const invocation = await invokeAgent({ task, item, nonce, config });
486	  if (invocation.ok) {
487	    await api.comment(gh, repo, item.number,
488	      `Agent session started${invocation.sessionUrl ? `: ${invocation.sessionUrl}` : ''}.`);
489	    log(`- #${item.number} ${id}: handed off${invocation.sessionId ? ` (${invocation.sessionId})` : ''}`);
490	    return 'agent';
491	  }
492	  if (invocation.answered) {
493	    // The endpoint refused, so no session exists and none will: a token, a URL or
494	    // a routine is wrong, and every future pick would be refused the same way.
495	    await converge(api, gh, repo, item, STATUS_RUNNING_AGENT, NEEDS_HUMAN_ACTION, claim,
496	      `Could not start an agent session: ${invocation.error}\n\nNo session was started. Fix the invocation endpoint, then re-queue this item (remove the \`${NEEDS_HUMAN}\` labels, add \`${READY}\`).`);
497	    return 'needs-human';
498	  }
499	  // NOTHING CAME BACK, and this is the case the whole design turns on: the call
500	  // may have started a session. Re-queueing here is what would put two sessions on
501	  // one item, and converging to triage would kill a run that is very possibly
502	  // alive. So the item STAYS with the agent and says the outcome is unknown —
503	  // whichever way it went is then settled by a rule that already exists: a session
504	  // that started converges the item, and one that never did leaves the item silent
505	  // until the janitor's agent leash sweeps it to triage.
506	  await api.comment(gh, repo, item.number,
507	    `The agent invocation got no answer: ${invocation.error}\n\n`
508	    + 'The session may or may not have started, so nothing here re-tries it — a second call could put two sessions on this item. '
509	    + `If a session did start it will converge this item; if it did not, the janitor's agent leash brings this item to \`${NEEDS_HUMAN}\` within a few hours.`);
510	  log(`! #${item.number} ${id}: invocation unanswered — left with the agent, leash decides — ${invocation.error}`);
511	  return 'unknown';
512	}
513	
514	// LETTING GO OF AN OPEN ITEM KILLS YOUR CLAIM (DESIGN §6.2, F24). An executor
515	// that stops owning an item without closing it — the roll, and every
516	// `needs-human` park — strikes its own claim by appending the episode marker to
517	// it. `claimWinner` already treats the last marker as the boundary, so a struck
518	// claim stops outranking anything and the next claimant wins on its first try.
519	//
520	// APPENDING rather than commenting is what lets the roll stay silent (§5): an
521	// hourly task that declines every hour adds no timeline entry. A successful
522	// hand-off deliberately does NOT strike — the episode is still live, owned by the
523	// agent session — and neither does a close, since nothing re-claims a closed item.
524	//
525	// Struck BEFORE the label swap, so the crash window degrades the safe way: an
526	// executor that dies between the two leaves the item `task:executing` with a
527	// spent claim, which the scheduler run's leash reclaim already recovers. Striking after
528	// would leave exactly the state this fixes — parked, re-queued by a human, and
529	// unclaimable forever.
530	async function strikeClaim(api, gh, repo, claim) {
531	  if (!claim || (claim.body ?? '').includes(EPISODE_MARKER)) return;
532	  await api.editComment(gh, repo, claim.id,
533	    `${claim.body}\n\n${EPISODE_MARKER}\nThis claim is spent — the executor released this item without closing it.`);
534	}
535	
536	// Every exit converges the item exactly once, with one comment saying what
537	// happened — the terminal-state discipline the incidents bought. The claim sits
538	// before the body so every state argument is grouped ahead of the prose.
539	//
540	// THE COMMENT CARRIES THE EXECUTION RECORD (DESIGN §6.5, §15.18). Actions logs
541	// expire, and for an agentless run — the majority — the item is the only durable
542	// trace there will ever be, so the record goes where the item is rather than into
543	// a log that ages out. The bracketed field is this item's issue number, which is
544	// the only join from a record back to the work it describes.
545	// A status of `null` writes NO record, and that is the honest answer for a park
546	// that is not a failure: the vocabulary's `success` means "ran to completion and
547	// the issue was closed" and `failed` means the run broke, so an approval park —
548	// a run that succeeded and left a PR for a person — is neither. Absence is a
549	// state of its own; inventing a fifth status is a change to stored data every
550	// decoder in the fleet would have to learn.
551	const recordFor = (item, status) => {
552	  // `item.taskId` is the resolved id — a marked issue's title names no task, so the
553	  // title parse alone would silently drop the record for every request run.
554	  const id = item.taskId ?? null;
555	  const parsed = status
556	    ? (id ? { pack: id.split('/')[0], task: id.split('/').slice(1).join('/') } : parseWorkItemTitle(item.title))
557	    : null;
558	  return parsed
559	    ? `\n\n\`\`\`\n${renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })}\n\`\`\``
560	    : '';
561	};
562	
563	// Park an item for a human. BOTH labels, always: `needs-human` is the state every
564	// guard and sweep reads, `triage` is what the human is being asked for.
565	async function converge(api, gh, repo, item, from, triage, claim, body, status = 'failed') {
566	  await strikeClaim(api, gh, repo, claim);
567	  await api.comment(gh, repo, item.number, body + recordFor(item, status));
568	  await swapStatus(api, gh, repo, item, from, NEEDS_HUMAN);
569	  await api.addLabel(gh, repo, item.number, triage);
570	}
571	
572	// A close is also the moment a dependent may become due (§15.19): whoever closes
573	// an item releases what it was holding, in code, and this run's next pick then
574	// finds it. The scheduler run stays the backstop for every close this code never
575	// performs — a human's, or a session that stopped early.
576	async function close(api, gh, repo, item, from, outcome, stateReason, body, status, ctx = {}) {
577	  await api.comment(gh, repo, item.number, body + recordFor(item, status));
578	  await clearStatus(api, gh, repo, item, from);
579	  await api.addLabel(gh, repo, item.number, outcome);
580	  // A MARKED ISSUE IS NOT THE RUN'S TO CLOSE (§16.1, §16.5). The item's terminal
581	  // status stands on the still-open issue: the run's verdict is about the run, and
582	  // whether the issue is finished belongs to the person who opened it. Nothing is
583	  // released either — a dependent waits for that issue to close, and it has not.
584	  if (!isWorkItemTitle(item.title)) return;
585	  await api.closeIssue(gh, repo, item.number, stateReason);
586	  await readyDependents(api, gh, repo, item.number, ctx);
587	}
588	
589	// --- CLI ----------------------------------------------------------------------
590	
591	async function main() {
592	  // THE OPERATOR HOLD, FIRST ACT (§15.24) — before the config load, before the
593	  // first API call, so a held queue reads nothing and writes nothing rather than
594	  // deriving the world and then declining to act on it.
595	  if (isSuspended()) { console.log('## Claudinite executor\n'); console.log(suspendedNotice()); return; }
596	  const { makeGh, actionRepoContext } = await import('../signals/gh.mjs');
597	  const { discoverTasks } = await import('../discover.mjs');
598	  const { loadConfig, isDormant } = await import('../../checks/helpers/repo-context.mjs');
599	  const { ensureLabels } = await import('../github.mjs');
600	  const { collectSignalsForTask } = await import('./signals.mjs');
601	  const { codeWorkRunner } = await import('./code-work-run.mjs');
602	  const { agentInvoker } = await import('./invoke.mjs');
603	
604	  const root = process.cwd();
605	  const { repo, defaultBranch } = actionRepoContext();
606	  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
607	  const config = loadConfig(root);
608	
609	  console.log('## Claudinite executor\n');
610	  if (isDormant(config)) {
611	    console.log('- this project declares itself dormant — nothing is picked up');
612	    return;
613	  }
614	
615	  const gh = makeGh();
616	  const { tasks, errors } = await discoverTasks(root, config);
617	  for (const e of errors) console.log(`! ${e.what}`);
618	  await ensureLabels(gh, repo, QUEUE_LABELS);
619	
620	  const runUrl = process.env.GITHUB_RUN_ID
621	    ? `${process.env.GITHUB_SERVER_URL ?? 'https://github.com'}/${repo}/actions/runs/${process.env.GITHUB_RUN_ID}`
622	    : null;
623	
624	  const done = await runExecutor({
625	    gh, repo, root, config, tasks,
626	    executorId: process.env.CLAUDINITE_EXECUTOR_ID || `actions-${process.env.GITHUB_RUN_ID ?? 'local'}`,
627	    runUrl,
628	    collectSignalsFor: collectSignalsForTask({ gh, repo, root, config, defaultBranch }),
629	    runTaskCodeWork: codeWorkRunner({ root, repo, defaultBranch }),
630	    invokeAgent: agentInvoker({ repo, config }),
631	    heldNow: () => readSuspendedNow(gh, repo, { log: console.log }),
632	  });
633	
634	  console.log(done.length
635	    ? done.map((d) => `- #${d.issue}: ${d.outcome}`).join('\n')
636	    : '- nothing ready to pick up');
637	}
638	
639	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
640	  main().catch((e) => { console.error(e); process.exit(1); });
641	}
642

