36:export const STATUS_RUNNING_AGENT = `${STATUS_PREFIX}running-agent`;
76:export const AGENT = 'task:agent';
77:export const NEEDS_HUMAN = 'needs-human';
99:export const TASK_DONE = 'task:done';
323:export const QUEUE_LABELS = [
---renderTaskExec---
// The machine-readable records a task's execution leaves in an Actions log
// (skill-usage-metrics DESIGN §4.2), and the parsers that read them back.
//
// TWO FAMILIES, ONE OF THEM HISTORICAL. `claudinite-task-run` was the SLOT
// scheduler's own line, one per due task per run; the slot scheduler is retired
// (#974) and nothing writes that line any more. The parser stays, and only the
// parser: Actions logs from before the retirement are still inside their retention
// window, and the usage fold still counts them. Nothing new should be taught this
// shape — `claudinite-task-exec` below is the live record.
//
// The counts these produce are exact within the Actions log retention window, and
// that is worth stating next to the capture-derived counts they land beside.

// The five things a slot scheduler run could do with a due task. One name per
// outcome, used verbatim as the counter key in the aggregate, so there is no
// mapping table between "what the run said" and "what the fold counted" to drift.
export const TASK_RUN_OUTCOMES = Object.freeze([
  // A dispatch issue was filed: an agent session ran this task.
  'agent',
  // The task ran with NO agent — an `agent_model: none` task (code-work is the
  // whole task), or an agentful one whose code-work requested no agent phase.
  // Kebab, not the declaration field's `code_work`: this word is a WIRE token,
  // constrained to the line format's `[a-z-]+` charset.
  'code-work',
  // Due, but its precondition said there was nothing to do.
  'skipped',
  // Its code-work failed; the run converged the task to a needs-human issue.
  'failed',
  // Due and past its precondition, but no NEW agent run started: this slot was
  // already dispatched (exactly-once), an earlier dispatch is still open
  // (at-most-one-open), or another task claimed the run exclusively. Work that
  // was wanted and did not happen this run.
  'deferred',
]);

// An empty per-task counter row — every outcome present, zeros included, so a row's
// shape never depends on which outcomes a task happened to hit.
export const emptyTaskRun = () => Object.fromEntries(TASK_RUN_OUTCOMES.map((o) => [o, 0]));

// The line format. `v1` is the shape's version: a reader that meets a `v2` line
---clearStatus---
// APPLYING a status transition — the write half of the vocabulary whose read half
// is `work-item.mjs`'s decode (tasks-dispatch DESIGN §4, the migration of #1119).
//
// One rule, and it is why this is not a plain `swapLabel`: the item may wear ANY
// engine version's spelling of the status it is leaving. A member's items outlive
// its converges, so an item filed as `task:ready` is picked up by an engine that
// writes `task:status:waiting-for-executor`, and a swap that named one spelling
// would leave the other standing — an item wearing two live statuses, which is the
// torn state the janitor exists to repair.
//
// Writes stay granular (add and remove named labels, never a set-write): with
// several executors and a scheduler run moving labels at once, a set-write from a
// stale snapshot clobbers a concurrent transition (DESIGN §4).
// The removes are UNCONDITIONAL — every spelling of the status being left, not
// only the ones the caller's snapshot shows. A caller holds the labels it read
// before its own earlier transitions, so filtering on that snapshot would skip
// exactly the label this engine just wrote; removing a label an issue does not
// carry 404s, which is the end state asked for and therefore success.
import { spellingsOf } from './work-item.mjs';

// Move `item` out of `fromStatus` (canonical — every spelling of it goes) and into
// the label `to`, which is whatever spelling this engine writes.
export async function swapStatus(api, gh, repo, item, fromStatus, to) {
  await clearStatus(api, gh, repo, item, fromStatus);
  return api.addLabel(gh, repo, item.number, to);
}

// Leave a status without entering another — the close path, where the terminal
// label is applied separately.
export async function clearStatus(api, gh, repo, item, status) {
  for (const label of spellingsOf(status)) {
    await api.removeLabel(gh, repo, item.number, label);
  }
}

